function payload( $type = 'payment.captured', $event_id = 'evt_1', $overrides = array() ) { $entity = array( 'id' => 'pay_test123', 'order_id' => 'order_test123', 'amount' => 1250, 'currency' => 'INR', 'status' => 'captured' ); if ( 'order.paid' === $type ) { $entity = array( 'id' => 'order_test123', 'amount_paid' => 1250, 'currency' => 'INR' ); $key = 'order'; } else { $key = 'payment'; } $event = array_merge( array( 'id' => $event_id, 'event' => $type, 'payload' => array( $key => array( 'entity' => $entity ) ) ), $overrides ); return json_encode( $event ); }
